SELECT "c_sales_org_master"."Email" "v_sales_employee_metric__employee_email", "c_sales_org_master"."Commissions_Plan_Level" "v_sales_employee_metric__commissions_plan_level", sum(CASE WHEN "c_sales_employee_metric".TEAM IN ('?') AND "c_sales_employee_metric".sal_org_role IN ('?') AND "c_sales_employee_metric".metric_name IN ('?') THEN "c_sales_employee_metric".metric_value WHEN "c_sales_employee_metric".TEAM IN ('?') AND "c_sales_employee_metric".Commissions_Plan_Level in ('?','?') AND "c_sales_employee_metric".sal_org_role = '?' AND "c_sales_employee_metric".metric_name IN ('?') THEN "c_sales_employee_metric".metric_value WHEN "c_sales_employee_metric".TEAM IN ('?') AND "c_sales_employee_metric".Commissions_Plan_Level = '?' AND YEAR("c_sales_employee_metric".metric_ts) < '?' AND "c_sales_employee_metric".sal_org_role = '?' AND "c_sales_employee_metric".metric_name IN ('?') THEN "c_sales_employee_metric".metric_value WHEN "c_sales_employee_metric".TEAM IN ('?') AND "c_sales_employee_metric".Commissions_Plan_Level = '?' AND YEAR("c_sales_employee_metric".metric_ts) >= '?' AND "c_sales_employee_metric".sal_org_role = '?' AND am_csm_flag = '?' AND "c_sales_employee_metric".metric_name IN ('?') THEN "c_sales_employee_metric".metric_value WHEN "c_sales_employee_metric".TEAM IN ('?') AND "c_sales_employee_metric".Commissions_Plan_Level in ('?','?') AND "c_sales_employee_metric".sal_org_role = '?' AND "c_sales_employee_metric".metric_name IN ('?', '?','?','?') THEN "c_sales_employee_metric".metric_value WHEN "c_sales_employee_metric".TEAM IN ('?') AND "c_sales_employee_metric".Commissions_Plan_Level in ('?','?') AND "c_sales_employee_metric".sal_org_role = '?' AND "c_sales_employee_metric".metric_name IN ('?', '?','?','?') THEN "c_sales_employee_metric".metric_value WHEN "c_sales_employee_metric".TEAM IN ('?','?','?','?','?','?','?','?','?') AND YEAR(metric_ts) >= '?' AND MONTH(metric_ts) < '?' AND "c_sales_employee_metric".metric_name IN ('?','?','?','?') THEN "c_sales_employee_metric".metric_value WHEN "c_sales_employee_metric".Commissions_Plan_Level in ('?') AND "c_sales_employee_metric".sal_org_role in ('?','?','?','?') AND YEAR(metric_ts) >= '?' AND MONTH(metric_ts) >= '?' AND "c_sales_employee_metric".metric_name IN ('?','?') THEN "c_sales_employee_metric".metric_value WHEN "c_sales_employee_metric".sal_org_role in ('?','?','?') AND YEAR(metric_ts) >= '?' AND MONTH(metric_ts) >= '?' AND "c_sales_employee_metric".metric_name IN ('?','?') THEN "c_sales_employee_metric".metric_value else 0 END ) "v_sales_employee_metric__arr_bookings_actuals", round((sum(CASE WHEN "c_sales_employee_metric".metric_name IN ('?', '?','?') THEN "c_sales_employee_metric".metric_value ELSE 0 END ) +sum(CASE WHEN "c_sales_employee_metric".metric_name IN ('?', '?','?') THEN "c_sales_employee_metric".metric_value ELSE 0 END ) ) / NULLIF(sum(CASE WHEN "c_sales_employee_metric".TEAM IN ('?','?','?','?','?') AND "c_sales_employee_metric".metric_name IN ('?') THEN "c_sales_employee_metric".metric_value WHEN "c_sales_employee_metric".TEAM IN ('?') AND "c_sales_employee_metric".metric_name IN ('?') THEN "c_sales_employee_metric".metric_value WHEN "c_sales_employee_metric".TEAM IN ('?','?','?') AND "c_sales_employee_metric".metric_name IN ('?') THEN "c_sales_employee_metric".metric_value ELSE 0 END ),0),2) "v_sales_employee_metric__net_new_business_attainment", round(((sum(CASE WHEN "c_sales_employee_metric".TEAM IN ('?') AND "c_sales_employee_metric".sal_org_role IN ('?') AND "c_sales_employee_metric".metric_name IN ('?') THEN "c_sales_employee_metric".metric_value WHEN "c_sales_employee_metric".TEAM IN ('?') AND "c_sales_employee_metric".Commissions_Plan_Level in ('?','?') AND "c_sales_employee_metric".sal_org_role = '?' AND "c_sales_employee_metric".metric_name IN ('?') THEN "c_sales_employee_metric".metric_value WHEN "c_sales_employee_metric".TEAM IN ('?') AND "c_sales_employee_metric".Commissions_Plan_Level = '?' AND YEAR("c_sales_employee_metric".metric_ts) < '?' AND "c_sales_employee_metric".sal_org_role = '?' AND "c_sales_employee_metric".metric_name IN ('?') THEN "c_sales_employee_metric".metric_value WHEN "c_sales_employee_metric".TEAM IN ('?') AND "c_sales_employee_metric".Commissions_Plan_Level = '?' AND YEAR("c_sales_employee_metric".metric_ts) >= '?' AND "c_sales_employee_metric".sal_org_role = '?' AND am_csm_flag = '?' AND "c_sales_employee_metric".metric_name IN ('?') THEN "c_sales_employee_metric".metric_value WHEN "c_sales_employee_metric".TEAM IN ('?') AND "c_sales_employee_metric".Commissions_Plan_Level in ('?','?') AND "c_sales_employee_metric".sal_org_role = '?' AND "c_sales_employee_metric".metric_name IN ('?', '?','?','?') THEN "c_sales_employee_metric".metric_value WHEN "c_sales_employee_metric".TEAM IN ('?') AND "c_sales_employee_metric".Commissions_Plan_Level in ('?','?') AND "c_sales_employee_metric".sal_org_role = '?' AND "c_sales_employee_metric".metric_name IN ('?', '?','?','?') THEN "c_sales_employee_metric".metric_value WHEN "c_sales_employee_metric".TEAM IN ('?','?','?','?','?','?','?','?','?') AND YEAR(metric_ts) >= '?' AND MONTH(metric_ts) < '?' AND "c_sales_employee_metric".metric_name IN ('?','?','?','?') THEN "c_sales_employee_metric".metric_value WHEN "c_sales_employee_metric".Commissions_Plan_Level in ('?') AND "c_sales_employee_metric".sal_org_role in ('?','?','?','?') AND YEAR(metric_ts) >= '?' AND MONTH(metric_ts) >= '?' AND "c_sales_employee_metric".metric_name IN ('?','?') THEN "c_sales_employee_metric".metric_value WHEN "c_sales_employee_metric".sal_org_role in ('?','?','?') AND YEAR(metric_ts) >= '?' AND MONTH(metric_ts) >= '?' AND "c_sales_employee_metric".metric_name IN ('?','?') THEN "c_sales_employee_metric".metric_value else 0 END )) / NULLIF(sum(CASE WHEN "c_sales_employee_metric".TEAM IN ('?', '?') AND "c_sales_employee_metric".sal_org_role = '?' AND "c_sales_employee_metric".metric_name IN ('?') THEN "c_sales_employee_metric".metric_value WHEN "c_sales_employee_metric".TEAM IN ('?', '?') AND "c_sales_employee_metric".sal_org_role = '?' AND "c_sales_employee_metric".metric_name IN ('?') THEN "c_sales_employee_metric".metric_value WHEN "c_sales_employee_metric".TEAM IN ('?','?','?','?','?','?','?','?','?') AND "c_sales_employee_metric".metric_name IN ('?') THEN "c_sales_employee_metric".metric_value END ),0))*100,2) "v_sales_employee_metric__expansion_attainment" FROM (select '?' as base_cube, entity_id as employee_master_key, null as individual_target_key, a.additional_properties_json.sales_org_master_key as sales_org_master_key, a.additional_properties_json.am_csm_flag as am_csm_flag, a.additional_properties_json.bd_team as bd_team, a.additional_properties_json.bd_title as bd_title, cast(a.additional_properties_json.last_refresh_timestamp as timestamp) as last_refresh_timestamp, b.role as sal_org_role, b.commissions_plan_level, b.l2_manager_role, derived_l2_manager, derived_l3_manager, b.derived_l3_manager_team, b.tier, b.pod_id, b.team, b.theater, b.focus, metric_ts, metric_name, metric_type, split(entity_id, '?')[0] as entity_id, TRY_CAST(metric_value AS DECIMAL(18,4)) AS metric_value from bizanalytics_us.edw.employee_metric a left join (select * from bizanalytics_us.edw.v_sales_org_master WHERE dl_op<>'?' and is_current = '?' and is_deleted=0) b on a.additional_properties_json.sales_org_master_key=b.master_key union SELECT '?' as base_cube, null as employee_master_key, individual_target_key as individual_target_key, sales_org_master_key as sales_org_master_key, null as am_csm_flag, null as bd_team, null as bd_title, null as last_refresh_timestamp, sal_org_role as sal_org_role, commissions_plan_level, l2_manager_role, derived_l2_manager, derived_l3_manager, derived_l3_manager_team, tier, pod_id, team, theater, focus, metric_ts, metric_name, '?' AS metric_type, split(individual_target_key, '?')[0] as entity_id, TRY_CAST(metric_value AS DECIMAL(18,4)) AS metric_value FROM ( SELECT concat(lead_owner_email, '?', CAST(sales_close_month AS TIMESTAMP)) as individual_target_key, b.master_key as sales_org_master_key, CAST(sales_close_month AS TIMESTAMP) AS metric_ts, b.role as sal_org_role, b.commissions_plan_level, b.l2_manager_role, derived_l2_manager, derived_l3_manager, b.derived_l3_manager_team, b.tier as tier, b.team, b.theater, b.focus, a.pod_id as pod_id, CAST(sales_target AS DECIMAL(18,4)) AS sales_target, CAST(retention_rate_target AS DECIMAL(18,4)) AS retention_rate_target, CAST(CASE WHEN hunting_farming = '?'THEN sales_target ELSE 0 END AS DECIMAL(18,4)) AS sales_target_hunting, CAST(CASE WHEN hunting_farming = '?'THEN sales_target ELSE 0 END AS DECIMAL(18,4)) AS sales_target_farming, CASE WHEN a.pod_id IS NULL THEN 0 ELSE CAST(sum(sales_target) over (partition BY a.pod_id, sales_close_month ) AS DECIMAL(18,4)) END AS exp_target, CAST(churn_target AS DECIMAL(18,4)) AS churn_target, CAST(new_logo_addition_target AS DECIMAL(18,4)) AS new_logo_addition_target FROM bizanalytics_us.edw.rep_sales_target_master a left join (select * from bizanalytics_us.edw.v_sales_org_master WHERE dl_op<>'?' and is_current = '?' and is_deleted=0) b ON a.LEAD_OWNER_EMAIL = b.email AND CAST(a.SALES_CLOSE_MONTH AS DATE) BETWEEN CAST(b.start_month AS DATE) AND CAST(b.end_month AS DATE) WHERE a.dl_op <> '?'AND a.is_current = '?' AND a.is_deleted = 0 AND a.target_flag = '?' ) LATERAL VIEW stack(9,'?', sales_target, '?',retention_rate_target, '?',sales_target_farming, '?',sales_target_hunting, '?',exp_target, '?',churn_target, '?',new_logo_addition_target ) s AS metric_name, metric_value ) AS "c_sales_employee_metric" LEFT JOIN (select * from bizanalytics_us.edw.v_sales_org_master WHERE dl_op<>'?' and is_current = '?' and is_deleted=0 ) AS "c_sales_org_master" ON "c_sales_employee_metric".sales_org_master_key = "c_sales_org_master".master_key LEFT JOIN bi_common.calendar_dim AS "calendar_dim" ON date("c_sales_employee_metric".metric_ts) = "calendar_dim".date WHERE ("calendar_dim"."DATE" >= $1::timestamptz AND "calendar_dim"."DATE" <= $2::timestamptz) AND ("c_sales_org_master"."Theater" = $3) GROUP BY 1, 2 ORDER BY 3 DESC LIMIT 5
